var parameters = {
    "id":"ggb",
    "width":1100,
    "height":600,
    "showToolBar":false,
    "borderColor":null,
    "showMenuBar":false,
    "showAlgebraInput":false,
    "showResetIcon":false,
    "enableLabelDrags":false,
    "enableShiftDragZoom":true,
    "enableRightClick":false,
    "capturingThreshold":null,
    "showToolBarHelp":false,
    "errorDialogsActive":false,
    "useBrowserForJS":true,
    "showFullscreenButton":true,
    "ggbBase64":""
};



var ggbApplet = new GGBApplet(parameters, '5.0');
ggbApplet.setHTML5Codebase("/vendor/geogebra/GeoGebra/HTML5/5.0/web3d/");
window.onload = function() {
    ggbApplet.inject('applet_container','preferHTML5');
}

ggb = document.ggb;

function exemplo2()
{
    document.getElementById("texto_exemplo1").style.display = "none";   
    
    ggb.evalCommand("f(x,y) = (x^2 - y^2)/(x^2 + y^2)");
    
    document.getElementById("texto_exemplo2").style.display = "block";
    document.getElementById("funcao").placeholder = "(x^2 - y^2)/(x^2 + y^2)";
    document.getElementById("exemplo").style.height = "1040px";
}

function exemplo1()
{
    document.getElementById("texto_exemplo2").style.display = "none";
    
    ggb.evalCommand("f(x,y) = (x^2 + 2*y^2)/(x^2 - y^2)");
    
    document.getElementById("texto_exemplo1").style.display = "block";
    document.getElementById("funcao").placeholder = "(x^2 + 2*y^2)/(x^2 - y^2)";
    document.getElementById("exemplo").style.height = "1040px";
}

function gerarSuperficie() {

    document.getElementById("texto_exemplo1").style.display = "none";
    document.getElementById("texto_exemplo2").style.display = "none";

    var func = document.getElementById('funcao');

    var ponto = document.getElementById('ponto');

    ggb.evalCommand("f(x,y) ="+func.value);

    ggb.evalCommand("P = ("+ponto.value+")");

    ggb.evalCommand("c: (x - x(P))² + (y - y(P))² = 4");

    ggb.evalCommand("D = PointIn(c)");

    ggb.evalCommand("Valor = f(D)");

    ggb.evalCommand("L_D = (0,0,Valor)");

    ggb.evalCommand("A = (x(D),y(D),z(L_D))");


    ggb.evalCommand("Delete(α)");
    ggb.evalCommand("Delete(β)");

    ggb.setFixed("P",true);

    ggb.setVisible ("texto1", true);  
    ggb.setVisible ("g", false);
    ggb.setVisible ("h", false);
    ggb.setVisible("A",true);
    ggb.setVisible("L_D",true);
    ggb.setVisible("D",true);

    ggb.setColor("f",213,0,249);

    document.getElementById("butao1").class = "btn btn-primary";
    document.getElementById("butao2").class = "btn btn-primary";
    document.getElementById("exemplo").style.height = "700px";
    
}
